// План specs/addresses.md 3.2 (кейс AD-07). Admin, компания «test». Только просмотр.
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, setEnglish } from './address-helpers';
import { TEST_CLIENT_ADDRESS, TEST_CLIENT_ID, expectNoBrokenUnitFormat, expectUnitRightAfterStreet, textOf } from './address-display-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Адрес: Unit на странице клиента (#b2f74544)', () => {
  test('Customer page: header shows the address on one line with Unit right after the street #b2f74544 @desktop @prod-safe', async ({ page }) => {
    await setEnglish(page);
    await page.goto(`/CustomerDetail?id=${TEST_CLIENT_ID}`);

    const text = await textOf(page.locator('main'), TEST_CLIENT_ADDRESS);
    const lines = text.split('\n').map((l) => l.trim());

    const headerLine = lines.find((l) => TEST_CLIENT_ADDRESS.test(l)) ?? '';
    expectUnitRightAfterStreet(headerLine.slice(headerLine.indexOf('2221')), 'Шапка клиента «test»');
    // До исправления Unit шёл отдельной строкой под адресом.
    expect(lines.filter((l) => /^Unit\s+[\w-]+$/i.test(l)), 'отдельная строка «Unit …»').toEqual([]);
    expectNoBrokenUnitFormat(text, 'Страница клиента «test»');
  });
});
